(function applyStoreContact(){
  if(typeof RESTAURANTS === "undefined") return;
  RESTAURANTS.forEach(function(r){
    const c = STORE_CONTACT[r.id];
    if(!c) return;
    if(c.tabelogUrl) r.tabelogUrl = c.tabelogUrl;
    if(c.tel) r.tel = c.tel;
    if(c.address) r.address = c.address;
    if(c.station){ r.nearestStation = c.station; r.stationMeters = c.stationM; }
    r.facts = {};
    if(c.kids) r.facts.kids = c.kids;
    if(c.privateRoom) r.facts.privateRoom = true;
    if(c.counterOnly) r.facts.counterOnly = true;
  });
})();
